/**
 * Slack Notification Utilities
 */
const https = require('https');

/**
 * Format Slack message blocks for a single rule
 * @param {Object} params - Parameters for formatting
 * @param {string} params.ruleId - Rule identifier (e.g., 'rule1')
 * @param {string} params.ruleName - Human-readable rule name
 * @param {string} params.ruleEmoji - Emoji for the rule header
 * @param {Array} params.stocks - Array of matching stocks
 * @param {Function} params.formatStock - Function to format each stock line
 * @param {Object} params.config - Rule configuration (thresholds, etc.)
 * @returns {Array} Array of Slack block objects
 */
function formatSingleRuleBlocks({ ruleId, ruleName, ruleEmoji, stocks, formatStock, config }) {
    const blocks = [];

    blocks.push({
        type: 'header',
        text: {
            type: 'plain_text',
            text: `${ruleEmoji} ${ruleName}`,
            emoji: true
        }
    });

    const stockList = stocks.map(formatStock).join('\n');

    blocks.push(
        { type: 'divider' },
        {
            type: 'section',
            text: {
                type: 'mrkdwn',
                text: `${config.description || ''}\n${stockList}`
            }
        }
    );

    blocks.push(
        { type: 'divider' },
        {
            type: 'context',
            elements: [
                {
                    type: 'mrkdwn',
                    text: `🕙 ${new Date().toLocaleString('en-US', { timeZone: 'America/New_York' })} EST`
                }
            ]
        }
    );

    return blocks;
}

/**
 * Format Slack message blocks for multiple rules (orchestrator mode)
 * @param {Object} alerts - Object containing arrays of stocks for each rule
 * @returns {Array} Array of Slack block objects
 */
function formatMultiRuleBlocks(alerts) {
    const blocks = [];

    // Check if we have any downside alerts
    const hasDownside = alerts.rule1Stocks.length > 0 || alerts.rule2Stocks.length > 0;
    // Check if we have any upside alerts
    const hasUpside = alerts.rule3Stocks.length > 0 || alerts.rule4Stocks.length > 0 ||
                      alerts.rule5Stocks.length > 0 || alerts.rule6Stocks.length > 0;

    // DOWNSIDE ALERTS
    if (hasDownside) {
        blocks.push({
            type: 'header',
            text: {
                type: 'plain_text',
                text: '📉 Stock Drop Alerts',
                emoji: true
            }
        });

        // Rule 1: Daily drops
        if (alerts.rule1Stocks.length > 0) {
            const stockList = alerts.rule1Stocks.map(stock =>
                `• *${stock.symbol}*: $${stock.price.toFixed(2)} → *${stock.change1d.toFixed(2)}%*`
            ).join('\n');

            blocks.push(
                { type: 'divider' },
                {
                    type: 'section',
                    text: {
                        type: 'mrkdwn',
                        text: `*1-Day Drop (>${alerts.config.rule1Threshold}%)* - ${alerts.rule1Stocks.length} stock(s):\n${stockList}`
                    }
                }
            );
        }

        // Rule 2: 2-day drops
        if (alerts.rule2Stocks.length > 0) {
            const stockList = alerts.rule2Stocks.map(stock =>
                `• *${stock.symbol}*: $${stock.price.toFixed(2)} → *${stock.change2d.toFixed(2)}%* (2d)`
            ).join('\n');

            blocks.push(
                { type: 'divider' },
                {
                    type: 'section',
                    text: {
                        type: 'mrkdwn',
                        text: `*2-Day Drop (>${alerts.config.rule2Threshold}%)* - ${alerts.rule2Stocks.length} stock(s):\n${stockList}`
                    }
                }
            );
        }
    }

    // UPSIDE ALERTS
    if (hasUpside) {
        blocks.push({
            type: 'header',
            text: {
                type: 'plain_text',
                text: '📈 Upside Potential Alerts',
                emoji: true
            }
        });

        // Rule 3: Recovery Signal
        if (alerts.rule3Stocks.length > 0) {
            const stockList = alerts.rule3Stocks.map(stock =>
                `• *${stock.symbol}*: $${stock.price.toFixed(2)} | 5d: ${stock.change5d.toFixed(2)}% | Today: *+${stock.change1d.toFixed(2)}%*`
            ).join('\n');

            blocks.push(
                { type: 'divider' },
                {
                    type: 'section',
                    text: {
                        type: 'mrkdwn',
                        text: `*🔄 Recovery Signal* (5d drop >${alerts.config.rule3Threshold1}%, today up >${alerts.config.rule3Threshold2}%) - ${alerts.rule3Stocks.length} stock(s):\n${stockList}`
                    }
                }
            );
        }

        // Rule 4: Near 52-Week Low
        if (alerts.rule4Stocks.length > 0) {
            const stockList = alerts.rule4Stocks.map(stock =>
                `• *${stock.symbol}*: $${stock.price.toFixed(2)} | 52w Low: $${stock.fiftyTwoWeekLow.toFixed(2)} (*+${stock.distanceFrom52wLow.toFixed(2)}%* from low)`
            ).join('\n');

            blocks.push(
                { type: 'divider' },
                {
                    type: 'section',
                    text: {
                        type: 'mrkdwn',
                        text: `*📍 Near 52-Week Low* (within ${alerts.config.rule4Threshold}%) - ${alerts.rule4Stocks.length} stock(s):\n${stockList}`
                    }
                }
            );
        }

        // Rule 5: Bounce Back
        if (alerts.rule5Stocks.length > 0) {
            const stockList = alerts.rule5Stocks.map(stock =>
                `• *${stock.symbol}*: $${stock.price.toFixed(2)} | Yesterday: ${stock.yesterdayChange.toFixed(2)}% | Today: *+${stock.change1d.toFixed(2)}%*`
            ).join('\n');

            blocks.push(
                { type: 'divider' },
                {
                    type: 'section',
                    text: {
                        type: 'mrkdwn',
                        text: `*↩️ Bounce Back* (yesterday drop >${alerts.config.rule5Threshold1}%, today up >${alerts.config.rule5Threshold2}%) - ${alerts.rule5Stocks.length} stock(s):\n${stockList}`
                    }
                }
            );
        }

        // Rule 6: High Volume Surge
        if (alerts.rule6Stocks.length > 0) {
            const stockList = alerts.rule6Stocks.map(stock =>
                `• *${stock.symbol}*: $${stock.price.toFixed(2)} | Today: *+${stock.change1d.toFixed(2)}%* | Volume: *${stock.volumeRatio.toFixed(1)}x* avg`
            ).join('\n');

            blocks.push(
                { type: 'divider' },
                {
                    type: 'section',
                    text: {
                        type: 'mrkdwn',
                        text: `*🔥 High Volume Surge* (up >${alerts.config.rule6Threshold1}%, volume >${alerts.config.rule6Threshold2}x avg) - ${alerts.rule6Stocks.length} stock(s):\n${stockList}`
                    }
                }
            );
        }
    }

    blocks.push(
        { type: 'divider' },
        {
            type: 'context',
            elements: [
                {
                    type: 'mrkdwn',
                    text: `🕙 ${new Date().toLocaleString('en-US', { timeZone: 'America/New_York' })} EST`
                }
            ]
        }
    );

    return blocks;
}

/**
 * Send alert to Slack
 * @param {string} webhookUrl - Slack webhook URL
 * @param {Object|Array} content - Either an alerts object (multi-rule) or blocks array (single-rule)
 * @returns {Promise<string>} Response from Slack API
 */
async function sendSlackAlert(webhookUrl, content) {
    return new Promise((resolve, reject) => {
        if (!webhookUrl) {
            reject(new Error('Slack webhook URL not configured'));
            return;
        }

        const url = new URL(webhookUrl);

        // Determine if content is blocks array or alerts object
        const blocks = Array.isArray(content) ? content : formatMultiRuleBlocks(content);

        const message = { blocks };
        const postData = JSON.stringify(message);

        const options = {
            hostname: url.hostname,
            path: url.pathname,
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(postData)
            }
        };

        const req = https.request(options, (res) => {
            let data = '';
            res.on('data', chunk => data += chunk);
            res.on('end', () => {
                if (res.statusCode === 200) {
                    resolve(data);
                } else {
                    reject(new Error(`Slack API error: ${res.statusCode} - ${data}`));
                }
            });
        });

        req.on('error', reject);
        req.write(postData);
        req.end();
    });
}

module.exports = { sendSlackAlert, formatSingleRuleBlocks, formatMultiRuleBlocks };
